// Modules ProTracker des démos (base64) : tknodoom (MAT_2, Sun/DreamDealers), redhouse (MAT_6), alice (Flan), space (Fortune).
window.MUSIC = {"tknodoom": "", "redhouse": "", "alice": "", "space": ""};
window.musicBuffer = n => { const s = atob(MUSIC[n]), u = new Uint8Array(s.length); for (let i = 0; i < s.length; i++) u[i] = s.charCodeAt(i); return u.buffer; };
